import numpy as np

def initialize(distances: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    d = np.asarray(distances, dtype=float)
    n = d.shape[0]
    eps = 1e-12

    if d.size == 0:
        return d.copy(), d.copy()

    finite = np.isfinite(d)
    positive = finite & (d > 0)
    if np.any(positive):
        scale = np.median(d[positive])
    else:
        scale = 1.0
    if not np.isfinite(scale) or scale <= 0:
        scale = 1.0

    inv = np.zeros_like(d)
    inv[positive] = 1.0 / np.maximum(d[positive], eps)

    row_mean = np.zeros(n, dtype=float)
    for i in range(n):
        rp = positive[i]
        if np.any(rp):
            row_mean[i] = np.mean(d[i, rp])
        else:
            row_mean[i] = scale
    centrality = 1.0 / np.maximum(row_mean[:, None] + row_mean[None, :], eps)

    heuristic = inv * centrality
    if n > 1:
        np.fill_diagonal(heuristic, 0.0)
        heuristic = 0.5 * (heuristic + heuristic.T)

    mask = np.isfinite(heuristic) & (heuristic > 0)
    if np.any(mask):
        h = heuristic[mask]
        lo, hi = np.percentile(h, [5, 95]) if h.size > 1 else (h[0], h[0])
        if hi > lo:
            heuristic = np.clip((heuristic - lo) / (hi - lo), 0.0, 1.0)
        else:
            heuristic = heuristic / (h[0] + eps)
    else:
        heuristic = np.zeros_like(d)

    pheromone = 0.1 + heuristic
    pheromone = np.where(np.isfinite(pheromone), pheromone, 0.1)
    if n > 1:
        np.fill_diagonal(pheromone, 0.0)
        pheromone = 0.5 * (pheromone + pheromone.T)

    return heuristic, pheromone
